class StrengthFinder:
    def __init__(self, class_name, extensions):
        self.class_name = class_name
        self.extensions = extensions

    def strength(self, ext):
        up = sum(1 for c in ext if c.isupper())
        low = sum(1 for c in ext if c.islower())
        return up - low

    def best_extension(self):
        if not self.extensions:
            return None
        strengths = [(ext, self.strength(ext)) for ext in self.extensions]
        max_strength = max(s for _, s in strengths)
        for ext, s in strengths:
            if s == max_strength:
                return f"{self.class_name}.{ext}"
        return None

# Example usage:
