class Soldier:
    def __init__(self, name, strength):
        self.name = name
        self.strength = strength

class Army:
    def __init__(self):
        self.soldiers = []

    def add_soldier(self, soldier):
        if not isinstance(soldier, Soldier):
            raise TypeError("Only Soldier instances can be added")
        self.soldiers.append(soldier)

    def max_strength(self):
        if not self.soldiers:
            return None
        return max(s.strength for s in self.soldiers)

# Example usage
if __name__ == "__main__":
    army = Army()
    army.add_soldier(Soldier("Alice", 75))
    army.add_soldier(Soldier("Bob", 82))
    army.add_soldier(Soldier("Charlie", 68))
    print("Maximum strength:", army.max_strength())
