import sys

s = sys.stdin.read()
out = []
for c in s:
    if c.isalpha():
        c2 = c.swapcase()
    else:
        c2 = c
    if c2.lower() in ('a', 'e', 'i', 'o', 'u'):
        base = ord('A') if c2.isupper() else ord('a')
        new_char = chr(base + (ord(c2) - base + 2) % 26)
        out.append(new_char)
    else:
        out.append(c2)

sys.stdout.write(''.join(out))

class Strongest_Extension:
    def __init__(self, class_name, extensions):
        self.class_name = class_name
        self.extensions = extensions

    def strength(self, s):
        CAP = sum(1 for c in s if c.isupper())
        SM = sum(1 for c in s if c.islower())
        return CAP - SM

    def strongest(self):
        if not self.extensions:
            return self.class_name
        # compute strength for each extension
        strengths = [self.strength(ext) for ext in self.extensions]
        max_strength = max(strengths)
        # find first extension with max strength
        for ext, st in zip(self.extensions, strengths):
            if st == max_strength:
                return f"{self.class_name}.{ext}"
        return self.class_name

